// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testFuzz_property(address owner, address operator, bool approved) public {
        vm.assume(owner != operator);
        vm.prank(owner);
        c.setApprovalForAll(operator, approved);
        bool result = c.isApprovedForAll(owner, operator);
        assertTrue(result == approved);
    }
}
